using Microsoft.EntityFrameworkCore;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Net.Mail;
namespace Society.Api;
public record WelcomeDefaultWrite(string Kind,string TemplateId);
public static class MemberSelfEmail {
 public const string TemplateName="member-self-email-html";
 static readonly string[] Kinds=["Individual","Institutional"];
 public static string Default(JsonObject profile,string kind)=>profile["memberWelcomeDefaults"]?[kind]?.ToString() is string saved&&MemberWelcome.Templates.Any(t=>t.Id==saved&&t.Kind==kind)?saved:kind=="Individual"?"individual-classic":"institutional-classic";
 static async Task<Membership> Owned(AppDb db,Guid tenant,Guid member,Guid user)=>await MembershipExperience.Owned(db,user,true).SingleOrDefaultAsync(m=>m.TenantId==tenant&&m.Id==member)??throw new AccessDeniedException();
 static async Task<string?> Recipient(AppDb db,Guid user)=>await db.Users.Where(u=>u.Id==user&&u.EmailConfirmed).Select(u=>u.Email).SingleOrDefaultAsync();
 public static async Task<bool> Allowed(AppDb db,Membership m,Guid user,string? email){if(!MemberWelcome.Eligible(m)||!MailAddress.TryCreate(email,out _)||!await PlatformPolicy.WorkAllowed(db,m.TenantId,"membership"))return false;return !await db.Set<CommunicationSuppression>().AnyAsync(s=>s.TenantId==m.TenantId&&s.Channel=="Email"&&s.DestinationHash==CommunityService.Hash(email!.ToLowerInvariant()));}
 static async Task<string> Kind(AppDb db,Membership m){var kind=await db.MembershipCategories.Where(c=>c.TenantId==m.TenantId&&c.Id==m.CategoryId).Select(c=>c.Kind).SingleAsync();if(!Kinds.Contains(kind))throw new DomainException("Membership email is available for Individual and Institutional memberships");return kind;}
 static IQueryable<Outbox> Requests(AppDb db,Guid tenant,Guid member,Guid user)=>db.Outbox.Where(o=>o.TenantId==tenant&&o.MembershipId==member&&o.UserId==user&&o.TemplateName==TemplateName);
 static async Task<object> Status(AppDb db,Guid tenant,Membership m,Guid user){var kind=await Kind(db,m);var email=await Recipient(db,user);var profile=MembershipService.Json(await db.Tenants.Where(t=>t.Id==tenant).Select(t=>t.Profile).SingleAsync());var template=MemberWelcome.Templates.Single(t=>t.Id==Default(profile,kind));var requests=Requests(db,tenant,m.Id,user);var latest=await requests.OrderByDescending(o=>o.CreatedAt).FirstOrDefaultAsync();var next=latest?.CreatedAt.AddMinutes(15);var dayStart=DateTimeOffset.UtcNow.AddHours(-24);var count=await requests.CountAsync(o=>o.CreatedAt>dayStart);if(count>=3){var oldest=await requests.Where(o=>o.CreatedAt>dayStart).OrderBy(o=>o.CreatedAt).Select(o=>o.CreatedAt).FirstAsync();var daily=oldest.AddHours(24);if(next==null||daily>next)next=daily;}var pending=latest!=null&&new[]{"Queued","Retry","Processing","Held","Unknown"}.Contains(latest.Status);var eligible=await Allowed(db,m,user,email);return new{recipient=email??"",templateId=template.Id,templateName=template.Name,membershipNumber=m.Number,validFrom=PlatformMemberAdmin.Date(m.EffectiveFrom).ToString("dd MMM yyyy"),validTill=m.EndsAt==null?"No expiry recorded":PlatformMemberAdmin.Date(m.EndsAt.Value.AddTicks(-1)).ToString("dd MMM yyyy"),canRequest=eligible&&!pending&&(next==null||next<=DateTimeOffset.UtcNow),nextRequestAt=next,reason=email==null?"Verify your account email to request a copy.":!eligible?"An active, paid membership with an ID and an available email address is required.":pending?"Your previous request is still queued or needs delivery review.":next>DateTimeOffset.UtcNow?"Please wait before requesting another copy.":null,lastRequest=latest==null?null:new{latest.Status,latest.CreatedAt,latest.SentAt}};}
 static async Task DefaultsAccess(Guid tenant,Access a){if(await a.Platform())return;await a.Require(tenant,"communications.templates");}
 public static void Map(RouteGroupBuilder t){
  t.MapGet("/defaults",async(Guid tenant,AppDb db,Access a)=>{await DefaultsAccess(tenant,a);var p=MembershipService.Json(await db.Tenants.Where(x=>x.Id==tenant).Select(x=>x.Profile).SingleAsync());return Kinds.ToDictionary(k=>k,k=>Default(p,k));});
  t.MapPut("/defaults",async(Guid tenant,WelcomeDefaultWrite r,AppDb db,Access a)=>{if(await a.Platform())await a.RequirePlatform();else await a.Require(tenant,"communications.templates");if(!Kinds.Contains(r.Kind)||!MemberWelcome.Templates.Any(t=>t.Kind==r.Kind&&t.Id==r.TemplateId))throw new DomainException("Choose a template matching the membership type");await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var society=await db.Tenants.SingleOrDefaultAsync(x=>x.Id==tenant)??throw new AccessDeniedException();var p=MembershipService.Json(society.Profile);var defaults=p["memberWelcomeDefaults"] as JsonObject??new JsonObject();defaults[r.Kind]=r.TemplateId;p["memberWelcomeDefaults"]=defaults;society.Profile=p.ToJsonString();a.Audit(tenant,"membership.welcome.default.changed",tenant,new{r.Kind,r.TemplateId});await db.SaveChangesAsync();await tx.CommitAsync();return Results.NoContent();});
  t.MapGet("/self/{id:guid}",async(Guid tenant,Guid id,AppDb db,Access a)=>await Status(db,tenant,await Owned(db,tenant,id,a.UserId),a.UserId));
  t.MapPost("/self/{id:guid}/request",async(Guid tenant,Guid id,AppDb db,Access a,IConfiguration config)=>{await using var tx=await db.Database.BeginTransactionAsync();await MembershipService.Lock(db,tenant);var m=await Owned(db,tenant,id,a.UserId);var state=JsonSerializer.SerializeToElement(await Status(db,tenant,m,a.UserId));if(!state.GetProperty("canRequest").GetBoolean())throw new DomainException(state.GetProperty("reason").GetString()??"Please wait before requesting another copy");var email=state.GetProperty("recipient").GetString()!;var template=state.GetProperty("templateId").GetString()!;var preview=JsonSerializer.SerializeToElement(await MemberWelcome.Preview(db,config,m,template,email));var job=new Outbox{TenantId=tenant,UnitId=m.ChapterId,MembershipId=m.Id,SenderId=a.UserId,UserId=a.UserId,Recipient=email,Subject=preview.GetProperty("subject").GetString()!,Body=preview.GetProperty("html").GetString()!,TemplateName=TemplateName,IdempotencyKey="member-self-email:"+Guid.NewGuid(),TemplateParameters=JsonSerializer.Serialize(new{number=m.Number,from=m.EffectiveFrom,till=m.EndsAt})};db.Add(job);a.Audit(tenant,"membership.email.self.requested",m.Id,new{outboxId=job.Id,template,m.Number});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{job.Id,job.Status});});
 }
 public static async Task<bool> CanDispatch(AppDb db,Outbox job){if(job.TenantId==null||job.MembershipId==null||job.UserId==null||job.SenderId!=job.UserId||job.IdempotencyKey?.StartsWith("member-self-email:")!=true)return false;var m=await MembershipExperience.Owned(db,job.UserId.Value,true).SingleOrDefaultAsync(m=>m.TenantId==job.TenantId&&m.Id==job.MembershipId);if(m==null)return false;var email=await Recipient(db,job.UserId.Value);if(!string.Equals(email,job.Recipient,StringComparison.OrdinalIgnoreCase)||!await Allowed(db,m,job.UserId.Value,email))return false;var snapshot=JsonSerializer.Deserialize<JsonElement>(job.TemplateParameters);return snapshot.GetProperty("number").GetString()==m.Number&&snapshot.GetProperty("from").GetDateTimeOffset()==m.EffectiveFrom&&(snapshot.GetProperty("till").ValueKind==JsonValueKind.Null?m.EndsAt==null:snapshot.GetProperty("till").GetDateTimeOffset()==m.EndsAt);}
}
